effect.shader:
// ------------------------------------------------------------------ sorteio
float h2(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

/** Ruído de valor entre −1 e 1 (bilinear suavizado). */
float ruido(vec2 p, float semente) {
    vec2 i = floor(p), f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = h2(i + semente), b = h2(i + vec2(1.0, 0.0) + semente);
    float c = h2(i + vec2(0.0, 1.0) + semente), d = h2(i + vec2(1.0, 1.0) + semente);
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y) * 2.0 - 1.0;
}

// ------------------------------------------------------------------ medidas
/** O tamanho do quadro CHEIO (os passes de glow rodam em meia resolução). */
vec2 quadro() { return vec2(textureSize(inputImg, 0)); }
/** Pixels do buffer por unidade do plugin: as medidas dele são em pixels de um quadro de 486 linhas. */
float unidade() { return effectScale / 100.0 * quadro().y / 486.0; }
/** O tempo do efeito: ele só anda `Frame Rate` vezes por segundo. */
float tempoDoEfeito() { return floor(acTime * frameRate + 1e-3) / frameRate; }
float quadroDoEfeito() { return floor(acTime * frameRate + 1e-3); }
float dano() { return 1.0 + float(moreDamage); }

/*
 * OS EVENTOS — medido em 1800 quadros: o tempo é uma fila de trechos de `dur` segundos (cada um
 * esticado ou encolhido em até ±variação), e cada trecho sorteia se o defeito acontece nele
 * (trechos seguidos emendam). Aqui: grade de `dur` com as divisas tremidas — a mesma estatística,
 * sem memória entre quadros. `inicio` = quando o trecho começou; `k` = o número dele.
 */
bool evento(float dur, float variacao, float chance, float semente, out float inicio, out float k) {
    inicio = 0.0; k = 0.0;
    float s = semente + randomSeed * 0.731;
    if (punchIt) return true;
    float t = acTime;
    dur = max(dur, 0.01);
    float v = clamp(variacao / 100.0, 0.0, 1.0);
    float k0 = floor(t / dur);
    float c = chance / 100.0 * (1.0 + 0.25 * float(moreOften));
    for (int i = -1; i <= 1; i++) {
        float kk = k0 + float(i);
        float b0 = (kk + v * (h2(vec2(kk, s)) - 0.5)) * dur;
        float b1 = (kk + 1.0 + v * (h2(vec2(kk + 1.0, s)) - 0.5)) * dur;
        if (t >= b0 && t < b1) { inicio = b0; k = kk; return h2(vec2(kk, s + 7.7)) < c; }
    }
    return false;
}

vec4 pre(vec4 c) { return vec4(c.rgb * c.a, c.a); }

// ------------------------------------------------------------------ passe 0: geometria + cor + linhas + estática
vec3 overlay(vec3 a, float b) { return mix(2.0 * a * b, 1.0 - 2.0 * (1.0 - a) * (1.0 - b), step(0.5, a)); }
vec3 overlay3(vec3 a, vec3 b) { return mix(2.0 * a * b, 1.0 - 2.0 * (1.0 - a) * (1.0 - b), step(0.5, a)); }

/** Tritone linear pela luma Rec. 709 (medido: 0,2127 / 0,7152 / 0,0720). */
vec3 colorir(vec3 c) {
    float l = dot(c, vec3(0.2126, 0.7152, 0.0722));
    l = l + sourceBrightness / 255.0;
    l = clamp(1.0 - (1.0 - l) * (1.0 + sourceContrast / 100.0), 0.0, 1.0);   // o contraste gira em volta do BRANCO
    vec3 t = l < 0.5 ? mix(colorShadows.rgb, colorMidtones.rgb, l * 2.0) : mix(colorMidtones.rgb, colorHighlights.rgb, l * 2.0 - 1.0);
    return mix(c, t, colorizePct / 100.0);
}

/** Uma camada de faixas: o cinza sorteado da faixa e a opacidade (pisca a cada X quadros). */
vec3 faixas(vec3 c, float y, float sentido, float vel, float altura, float semente, float opMin, float opMax, float strobe, bool fade) {
    float h = max(altura * effectScale / 100.0 * quadro().y / 715.5, 1.0);
    // A velocidade é em pixels da COMPOSIÇÃO por segundo, em qualquer resolução (medido em 90p, 360p e 720p).
    float andou = vel * acEscalaDePixel * tempoDoEfeito() * sentido;
    float i = floor((y + andou) / h);
    float b = h2(vec2(i + semente, 17.0 + sentido * 3.0));
    float q = floor(tempoDoEfeito() / (acFrameDuration > 0.0 ? acFrameDuration : 1.0 / 30.0) + 0.5);
    float fase = q / max(strobe, 1.0);
    float m = fade ? abs(mod(fase, 2.0) - 1.0) : 1.0 - mod(floor(fase), 2.0);    // 1 = opacidade máxima
    float op = mix(opMin, opMax, m) / 100.0;
    return mix(c, overlay(c, b), op);
}

/** A estática: um grão cinza por célula (N = 0,854·u^2,7), em overlay. */
float graoDaEstatica(vec2 px) {
    float hc = quadro().y / acEscalaDePixel;                               // altura em pixels da composição
    float a = min((0.13 + 0.008 * staticSize) * pow(hc / 1080.0, 0.8) * effectScale / 100.0, 0.95);
    float cel = max(hc / 244.0 / (1.0 - a) * acEscalaDePixel, 1.0);
    vec2 p = px / vec2(cel, cel / 1.18);
    vec2 i = floor(p), f = clamp((fract(p) - 0.3) / 0.4, 0.0, 1.0);
    float s = quadroDoEfeito() * 1.37 + randomSeed;
    float u = mix(mix(h2(i + s), h2(i + vec2(1.0, 0.0) + s), f.x), mix(h2(i + vec2(0.0, 1.0) + s), h2(i + vec2(1.0, 1.0) + s), f.x), f.y);
    return 0.008 + 0.854 * pow(u, 2.7);
}

/** O deslocamento "de TV" das distorções: riscos largos e baixos que tremem. */
vec2 tremor(vec2 px, float escala, float vel, vec2 forca, float semente) {
    float u = unidade();
    vec2 p = px / (max(escala, 1.0) * u * vec2(1.2, 0.2));
    float t = floor(acTime * max(vel, 1.0) / 23.0);
    return forca * u * 2.0 * vec2(ruido(p, semente + t * 3.7), ruido(p + 31.0, semente + t * 3.7 + 9.0));
}

/** De onde o pixel lê, depois dos defeitos de geometria. `furo` = o Glitch Holes apagou. */
vec2 geometria(vec2 px, out bool furo) {
    furo = false;
    vec2 res = quadro();
    float u = unidade();
    float ini, k;
    // Low-Res: blocos de 100/% unidades.
    float pct = 0.0;
    if (lowRes) pct = lowResPct;
    if (randomLowRes && evento(rlrDuration, rlrVariation, rlrChance, 31.0, ini, k)) pct = mix(rlrMin, rlrMax, h2(vec2(k, 32.0)));
    if (pct > 0.0 && pct < 100.0) { float b = max(u * 100.0 / pct, 1.0); px = floor(px / b) * b + 0.5; }
    // TV Roll: o quadro rola 0,154 da altura por segundo por unidade de velocidade, de um ponto sorteado.
    if (tvRoll && evento(rollDuration, rollVariation, rollChance, 41.0, ini, k)) {
        float volta = fract(h2(vec2(k, 42.0)) + rollSpeed * 0.154 * (tempoDoEfeito() - ini));
        px.y = mod(px.y + volta * res.y, res.y);
        if (tvDistortion && h2(vec2(k, 43.0)) < tvdChance / 100.0) {
            float comprimento = max(res.y * 0.12 * pow(tvdScale / 100.0, 8.0), 1.5);
            px.x += tvdAmount * res.x * 0.17 * ruido(vec2(px.y / comprimento, quadroDoEfeito() * 0.37), 44.0);
        }
    }
    // Glitch: blocos deslocados (até 1/4 do quadro por unidade de Displacement).
    if (glitch && evento(glitchDuration, glitchVariation, glitchChance, 51.0, ini, k)) {
        float g = floor(acTime * glitchSpeed);
        float hb = max(res.y * pow(10.0, (glitchSize - 215.0) / 40.0), 2.0);
        for (int n = 0; n < 5; n++) {
            if (float(n) >= glitchComplexity) break;
            vec2 cel = vec2(hb * glitchAspect, hb) / exp2(float(n));
            vec2 id = floor(px / cel) + vec2(g * 13.0 + float(n) * 71.0, randomSeed);
            if (h2(id) < glitchAmount / 100.0 / glitchComplexity * 1.6) {
                px += (vec2(h2(id + 3.3), h2(id + 8.8)) * 2.0 - 1.0) * vec2(glitchDispH, glitchDispV) * res * 0.25 * dano();
                break;
            }
        }
        if (glitchHoles && h2(vec2(k, 55.0)) < holesChance / 100.0) {
            float hh = max(res.y * pow(10.0, (holesSize - 215.0) / 40.0), 2.0);
            vec2 id = floor(px / (0.5 * vec2(hh * holesAspect, hh))) + vec2(g * 7.0, randomSeed + 5.0);
            furo = h2(id) < 0.25 * holesAmount / 100.0;
        }
    }
    // As três distorções: a tela toda, uma faixa que viaja e blocos.
    if (screenDistortion && evento(sdDuration, sdVariation, sdChance, 61.0, ini, k))
        px += tremor(px, sdScale, sdSpeed, vec2(sdStrengthX, sdStrengthY) * dano(), 62.0);
    if (traveling && evento(tdDuration, tdVariation, tdChance, 71.0, ini, k)) {
        float meia = tdLineHeight / 100.0 * res.y;
        float yc = mod(tdLineSpeed * res.y / 336.0 * (acTime - ini), res.y + 2.0 * meia) - meia;
        float w = clamp(1.0 - abs(px.y - yc) / meia, 0.0, 1.0);
        w = tdFalloff > 0.0 ? pow(w, tdFalloff * 0.5) : step(0.001, w);
        px += w * tremor(px, tdScale / 15.0, tdSpeed, vec2(tdStrengthX, tdStrengthY) * dano(), 72.0);
    }
    if (blockDistortion && evento(bdDuration, bdVariation, bdChance, 81.0, ini, k)) {
        float hb = max(bdSize * u * 0.31, 2.0);
        vec2 p = px / vec2(hb * bdAspect, hb);
        vec2 id = floor(p) + vec2(floor(acTime * bdBlockSpeed) * 5.0, randomSeed + 9.0);
        if (h2(id) < bdAmount / 100.0) {
            vec2 d = abs(fract(p) - 0.5) * 2.0;
            px += (1.0 - d.y * d.y) * tremor(px, bdScale, bdSpeed, vec2(bdStrengthX, bdStrengthY) * dano(), 82.0);
        }
    }
    return px;
}

vec4 passeBase(vec2 uv) {
    vec2 res = quadro();
    bool furo;
    vec2 px = geometria(uv * res, furo);
    vec2 q = px / res;
    if (furo) return vec4(0.0);
    vec4 s = texture(inputImg, fract(q));                           // o que sai de um lado entra pelo outro
    vec3 c = s.rgb;
    if (colorization) c = colorir(c);
    if (lines) {
        float y = uv.y * res.y;
        if (lineDirection != 1) c = faixas(c, y, 1.0, luSpeed, luHeight, luSeed, luOpacityMin, luOpacityMax, luStrobe, luFade);
        if (lineDirection != 0) c = faixas(c, y, -1.0, ldSpeed, ldHeight, ldSeed, ldOpacityMin, ldOpacityMax, ldStrobe, ldFade);
    }
    if (staticOn) c = mix(c, overlay(c, graoDaEstatica(uv * res)), staticOpacity / 100.0);
    if (colorNoise) {
        // Manchas de cor suaves (~5 px em 360 linhas com Scale 100; desvio 0,02 com opacidade 100), um sorteio por canal, em overlay.
        vec2 p = uv * res / (5.5 * res.y / 360.0 * noiseScale / 100.0);
        float sm = quadroDoEfeito() * 2.3 + randomSeed;
        vec3 n = vec3(ruido(p, sm), ruido(p + 19.0, sm + 5.0), ruido(p + 47.0, sm + 11.0));
        c = overlay3(c, 0.5 + 0.05 * noiseOpacity / 100.0 * n);
    }
    return pre(vec4(clamp(c, 0.0, 1.0), s.a));
}

// ------------------------------------------------------------------ passe 1: fantasma + separação + scan lines
vec4 lerBase(vec2 px) {
    vec2 q = px / quadro();
    if (q.x < 0.0 || q.x > 1.0 || q.y < 0.0 || q.y > 1.0) return vec4(0.0);
    return texture(base, q);
}

/** O fantasma num ponto: uma cópia da base deslocada (às vezes com a lente torta), já na opacidade dele. */
vec4 fantasma(vec2 px) {
    if (!ghost) return vec4(0.0);
    float q = quadroDoEfeito();
    float s = randomSeed * 0.917;
    // Um sorteio por quadro do efeito, sem duração (medido: trechos de 1 quadro).
    if (!punchIt && h2(vec2(q, 91.0 + s)) >= ghostChance / 100.0 * (1.0 + float(moreOften))) return vec4(0.0);
    float u = unidade() * dano();
    vec2 des = vec2(0.0);
    // O deslocamento sorteado é triangular em volta do meio da faixa (medido: metade da meia-faixa).
    if (h2(vec2(q, 92.0 + s)) < ghostXChance / 100.0)
        des.x = 0.5 * (ghostXMin + ghostXMax) + 0.25 * (ghostXMax - ghostXMin) * (h2(vec2(q, 93.0 + s)) + h2(vec2(q, 94.0 + s)) - 1.0);
    if (h2(vec2(q, 95.0 + s)) < ghostYChance / 100.0)
        des.y = 0.5 * (ghostYMin + ghostYMax) + 0.25 * (ghostYMax - ghostYMin) * (h2(vec2(q, 96.0 + s)) + h2(vec2(q, 97.0 + s)) - 1.0);
    vec2 p = px - des * u;
    if (ghostDistortion && h2(vec2(q, 98.0 + s)) < ghostDistChance / 100.0) {
        // Lente: desvio −0,0047·valor·r·(1 − r²/R²), R = meia diagonal (medido com ±30).
        vec2 res = quadro();
        vec2 centro = res * (0.5 + 0.15 * (vec2(h2(vec2(q, 99.0 + s)), h2(vec2(q, 100.0 + s))) - 0.5));
        vec2 d = p - centro;
        float r2 = dot(d, d) / (0.25 * dot(res, res));
        p += -0.0047 * mix(ghostDistMin, ghostDistMax, h2(vec2(q, 101.0 + s))) * d * (1.0 - r2);
    }
    return ghostOpacity / 100.0 * lerBase(p);
}

const float PERFIL_A[21] = float[21](0.0, 0.0201, 0.0714, 0.1568, 0.2618, 0.3801, 0.5007, 0.6176, 0.7196, 0.8028, 0.8729,
                                     0.9246, 0.9585, 0.9796, 0.9918, 0.9965, 0.9989, 0.9995, 0.9997, 0.9999, 1.0);
const float PERFIL_D[21] = float[21](0.0, 0.0066, 0.0233, 0.0502, 0.0833, 0.1229, 0.1691, 0.2256, 0.2924, 0.3651, 0.4520,
                                     0.5452, 0.6326, 0.7163, 0.7967, 0.8529, 0.9061, 0.9462, 0.9758, 0.9905, 1.0);

/**
 * A scan line num eixo: x = quanto o pixel está DENTRO da linha mais próxima (0 = na borda,
 * 1 = feather inteiro para dentro). Devolve (cor, alfa): o plugin escurece a cor mais devagar do
 * que devolve o alfa — as duas curvas foram tiradas dos renders (tools/holomatrix/benchmark).
 */
vec2 scanNoEixo(float coordPx) {
    float d = scanDistance, t = scanThickness;
    if (d <= 0.0) return vec2(1.0);
    float yu = coordPx / unidade();
    float meio = 0.5 * min(t, d);                                 // medido: o centro fica em min(t, d)/2
    float i = floor((yu - meio) / d + 0.5);
    float e = 0.5 * t - abs(yu - (i * d + meio));
    // O feather vai da borda PARA DENTRO, e tem ~1 pixel a mais do que o valor (medido com 3, 8, 24 e 48).
    float x = clamp(e / (scanFeather + 1.07 * acEscalaDePixel / unidade()), 0.0, 1.0) * 20.0;
    int n = int(min(floor(x), 19.0));
    float f = x - float(n);
    return vec2(mix(PERFIL_D[n], PERFIL_D[n + 1], f), mix(PERFIL_A[n], PERFIL_A[n + 1], f));
}

/** Quanto do quadro as scan lines deixam passar no alfa (a média de um período). */
float coberturaDaScan() {
    float soma = 0.0;
    float periodo = max(scanDistance, 1e-3) * unidade();
    for (int n = 0; n < 16; n++) soma += scanNoEixo((float(n) + 0.5) / 16.0 * periodo).y;
    return soma / 16.0;
}

/**
 * A base com o glow secundário, o fantasma e as scan lines num ponto. Medido: o fantasma é SOMADO
 * sem o glow secundário, e as scan lines valem para os dois; a separação de cor vem depois.
 */
vec4 comScan(vec2 px) {
    vec4 c = lerBase(px);
    vec4 f = fantasma(px);
    if (!scanLines) {
        // Glow secundário sem scan lines (medido): c·(1 + 2·borrão(c)), canal por canal.
        if (secondaryGlow) c.rgb = min(c.rgb * (1.0 + 2.0 * texture(sv, clamp(px / quadro(), 0.0, 1.0)).rgb), c.a);
        return min(c + f, 1.0);
    }
    vec2 m = scanDirection == 0 ? scanNoEixo(px.y) : scanDirection == 1 ? scanNoEixo(px.x) : min(scanNoEixo(px.y), scanNoEixo(px.x));
    if (secondaryGlow) {
        // Com o glow secundário as linhas não chegam ao preto: sobra ~30% da imagem no vão e a
        // linha fica 1,3–1,6× mais clara. Medido linha a linha em dois desenhos: o padrão (cobre
        // 75% do quadro: 1,6·m + 0,31) e linhas separadas (37%: 1,3·m + 0,3 + 0,76·m·cor).
        float t = clamp((coberturaDaScan() - 0.37) / 0.38, 0.0, 1.0);
        c = vec4(c.rgb * ((1.3 + 0.3 * t) * m.x + 0.3 + 0.76 * (1.0 - t) * m.x * c.rgb), c.a * (0.68 * m.y + 0.28));
    } else {
        c = vec4(c.rgb * m.x, c.a * m.y);
    }
    // O fantasma soma na cor; no alfa ele só completa o que faltava (a camada opaca continua opaca).
    float semLinhas = max(lerBase(px).a, 1e-4);
    // (A cor pode passar do alfa aqui: o limiar do glow olha para ela antes do corte da saída.)
    return vec4(min(c.rgb + f.rgb * m.x, 1.0), c.a * min(semLinhas + f.a, 1.0) / semLinhas);
}

vec4 passeMistura(vec2 uv) {
    vec2 res = quadro();
    vec2 px = uv * res;
    vec4 c;
    float ini, k;
    if (colorSeparation && evento(sepDuration, sepVariation, sepChance, 21.0, ini, k)) {
        // Vermelho lê à direita, azul à esquerda; o alfa é a UNIÃO dos três (1 − Π(1 − a), medido).
        vec2 d = vec2(sepAmount * unidade() * dano(), 0.0);
        vec4 r = comScan(px + d), g = comScan(px), b = comScan(px - d);
        c = vec4(r.r, g.g, b.b, 1.0 - (1.0 - r.a) * (1.0 - g.a) * (1.0 - b.a));
    } else {
        c = comScan(px);
    }
    return c;
}

// ------------------------------------------------------------------ glow
/** σ do glow em pixels do quadro cheio (medido em 360 linhas: 1,1 + 0,28·raio, nunca menos de 2,06). */
float sigmaDoGlow() { return quadro().y / 360.0 * max(2.06, 1.1 + 0.28 * glowRadius * effectScale / 100.0); }
float sigmaDoSegundo() { return quadro().y / 360.0 * max(0.8, 0.41 * secondaryGlowRadius * effectScale / 100.0); }
/** Com raio pequeno o glow é quase a própria imagem: só 0,236·raio dela vai para o borrão (medido com 1, 2 e 5). */
float parteBorrada() { return min(0.236 * glowRadius * effectScale / 100.0, 1.0); }

/** Só o que passa do limiar, canal por canal. O alfa vai inteiro: o borrão dele enche o vão das scan lines. */
vec4 limiar(vec4 c) { return vec4(c.rgb * step(glowThreshold / 100.0, c.rgb - 1e-4), c.a); }

/** Gaussiano de um eixo neste buffer (meia resolução). `fonte`: 0 = base, 1 = sh, 2 = lim, 3 = gh. */
vec4 borrar(int fonte, vec2 eixo, float sigmaCheio) {
    vec2 uv = acScreenNorm;
    float sigma = max(sigmaCheio * acResolution.y / quadro().y, 0.5);
    float passo = max(1.0, ceil(3.0 * sigma / 20.0));
    vec4 soma = vec4(0.0);
    float pesos = 0.0;
    for (int n = -20; n <= 20; n++) {
        float d = float(n) * passo;
        if (abs(d) > 3.0 * sigma + 0.5) continue;
        float w = exp(-0.5 * d * d / (sigma * sigma));
        vec2 q = uv + eixo * d * acTexelSize;
        vec4 v = vec4(0.0);
        if (q.x >= 0.0 && q.x <= 1.0 && q.y >= 0.0 && q.y <= 1.0) {
            if (fonte == 0) v = texture(base, q);
            else if (fonte == 1) v = texture(sh, q);
            else if (fonte == 2) v = texture(lim, q);
            else v = texture(gh, q);
        }
        soma += w * v;
        pesos += w;
    }
    return soma / max(pesos, 1e-6);
}

void main() {
    vec2 uv = acScreenNorm;
    if (acPass == 0) { fragColor = passeBase(uv); return; }
    if (acPass == 1) { fragColor = secondaryGlow ? borrar(0, vec2(1.0, 0.0), sigmaDoSegundo()) : vec4(0.0); return; }
    if (acPass == 2) { fragColor = secondaryGlow ? borrar(1, vec2(0.0, 1.0), sigmaDoSegundo()) : vec4(0.0); return; }
    if (acPass == 3) { fragColor = passeMistura(uv); return; }
    if (acPass == 4) {
        // O limiar é tirado pixel a pixel do quadro CHEIO (as scan lines têm 1–2 px: a média de
        // dois vizinhos ficaria abaixo dele e o glow sumiria) e só então cai para meia resolução.
        vec4 soma = vec4(0.0);
        if (glow) {
            vec2 d = 0.25 * acTexelSize;
            soma = 0.25 * (limiar(texture(mixado, uv + vec2(-d.x, -d.y))) + limiar(texture(mixado, uv + vec2(d.x, -d.y)))
                         + limiar(texture(mixado, uv + vec2(-d.x, d.y))) + limiar(texture(mixado, uv + d)));
        }
        fragColor = soma;
        return;
    }
    if (acPass == 5) { fragColor = glow ? borrar(2, vec2(1.0, 0.0), sigmaDoGlow()) : vec4(0.0); return; }
    if (acPass == 6) { fragColor = glow ? borrar(3, vec2(0.0, 1.0), sigmaDoGlow()) : vec4(0.0); return; }

    vec4 c = texture(mixado, uv);
    if (glow) {
        // A cor ganha Intensity × o que passa do limiar, borrado. O alfa NÃO depende do limiar nem
        // da Intensity (medido com 1, 3 e 6): é a união dele com o próprio borrão.
        vec4 borrao = texture(gv, uv);
        c.rgb = min(c.rgb + glowIntensity * mix(limiar(c).rgb, borrao.rgb, parteBorrada()), 1.0);
        c.a = 1.0 - (1.0 - c.a) * (1.0 - parteBorrada() * borrao.a);
    }
    c.rgb = min(c.rgb, c.a);
    float ini, k;
    if (flicker && evento(flickerDuration, flickerVariation, flickerChance, 11.0, ini, k)) {
        float g = mix(flickerMin, flickerMax, h2(vec2(quadroDoEfeito(), 12.0 + randomSeed))) / 100.0;
        c = vec4(c.rgb * g * g, c.a * g);                           // medido: a cor reta E o alfa caem juntos
    }
    vec4 original = pre(texture(inputImg, uv));
    c = mix(c, original, blendOriginal / 100.0);
    if (unmult) c.a = max(c.r, max(c.g, c.b));
    fragColor = c.a > 1e-5 ? vec4(min(c.rgb / c.a, 1.0), c.a) : vec4(0.0);
}
